-- Committed fixtures only for the companion two-session test in a disposable DB.
do $$begin if current_database()<>'byus_clean'or inet_server_addr()is not null then raise exception 'Disposable Unixsocket byus_clean required';end if;end $$;
begin;
create table public.group_wallet_cross_fixture(key text primary key,value jsonb not null);
do $$declare owner uuid:='e9500000-0000-4000-8000-000000000001';actor uuid:='e9500000-0000-4000-8000-000000000002';allowlist uuid:='e9500000-0000-4000-8000-000000000003';creator uuid;second_creator uuid:='e9500000-0000-4000-8000-000000000004';live uuid;benefit uuid:='e9500000-0000-4000-8000-000000000005';campaign uuid:='e9500000-0000-4000-8000-000000000006';capsule uuid;policy_a uuid;policy_b uuid;product uuid;intent uuid:='e9500000-0000-4000-8000-000000000007';pending uuid:='e9500000-0000-4000-8000-000000000008';tx uuid:=extensions.gen_random_uuid();page uuid:='e9500000-0000-4000-8000-000000000009';result jsonb;prior jsonb;ticket jsonb;point_entry uuid;slug text;at_time timestamptz:=clock_timestamp();begin
 if public.group_wallet_enabled()then raise exception 'Cross-feature setup requires disabled release baseline';end if;
 insert into public.app_users(id,privy_user_id,verified_email)values(owner,'did:privy:cross-wallet-owner','cross-wallet-owner@example.test'),(actor,'did:privy:cross-wallet-admin','cross-wallet-admin@example.test');
 insert into public.admin_allowlist(id,email,role,active)values(allowlist,'cross-wallet-admin@example.test','admin',true);
 insert into public.user_wallets(app_user_id,chain_id,address,provider,wallet_type)values(owner,91342,'0xe950000000000000000000000000000000000001','privy','embedded');
 select e.id,e.celebrity_id into live,creator from public.live_events e where e.publication_status='published'and e.archived_at is null and not exists(select 1 from public.live_benefit_campaigns c where c.live_event_id=e.id)order by e.id limit 1;
 if live is null then raise exception 'Published legacy LIVE fixture required';end if;
 select c.slug into slug from public.celebrities c where c.id=creator;
 insert into public.celebrities(id,slug,status,image_url,published_at,roles,primary_role)values(second_creator,'cross-wallet-second','published','/fixture.webp',now(),'{creator}','creator');
 insert into public.celebrity_localizations(celebrity_id,locale,name,summary,image_alt)values(second_creator,'ko','교차검증','검증용 크리에이터','검증 이미지'),(second_creator,'en','Cross fixture','Test Creator','Test image');
 insert into public.benefits select *from jsonb_populate_record(null::public.benefits,(select to_jsonb(b)from public.benefits b limit 1)||jsonb_build_object('id',benefit,'slug','cross-wallet-benefit','celebrity_id',creator,'delivery_type','text','allocation_mode','application_selection','publication_status','published','published_at',at_time,'archived_at',null,'claim_opens_at',at_time-interval'1 day','claim_closes_at',at_time+interval'1 day'));
 insert into public.benefit_delivery_vault(benefit_id,delivery_type,secret_value)values(benefit,'text','Fixture delivery');
 insert into public.benefit_localizations(benefit_id,locale,title,summary,eligibility_label,delivery_label)values(benefit,'ko','검증 경품','검증용','회원','디지털'),(benefit,'en','Fixture','Test benefit','Member','Digital');
 insert into public.live_benefit_campaigns(id,live_event_id,celebrity_id,status,entry_opens_at,entry_closes_at,actor_app_user_id,actor_admin_allowlist_id,published_at)values(campaign,live,null,'published',at_time-interval'1 hour',at_time+interval'1 day',actor,allowlist,at_time);
 insert into public.live_benefit_campaign_items(campaign_id,benefit_id,priority,per_fan_ticket_limit,winner_quantity,fulfillment_method)values(campaign,benefit,1,10,1,'digital');
 insert into public.mobile_fan_economy_policies(celebrity_id,version,kind,rules,effective_at,retired_at)values(creator,'cross-wallet-credit-v1','correction','{}',at_time,at_time)returning id into policy_a;
 insert into public.mobile_fan_economy_policies(celebrity_id,version,kind,rules,effective_at)values(second_creator,'cross-wallet-exchange-v1','exchange','{"free_draw":100}',at_time)returning id into policy_b;
 perform public.mobile_fan_economy_post(owner,creator,'fan_point',100,'cross_fixture',extensions.gen_random_uuid(),policy_a);
 perform public.mobile_fan_economy_post(owner,second_creator,'fan_point',200,'cross_fixture',extensions.gen_random_uuid(),policy_b);
 perform public.mobile_fan_economy_post(owner,creator,'paid_vote',9,'cross_fixture',extensions.gen_random_uuid(),policy_a);
 perform public.mobile_fan_economy_post(owner,creator,'free_vote',4,'cross_fixture',extensions.gen_random_uuid(),policy_a);
 -- Legacy free_draw exchange is closed; plant the committed historic exchange directly.
 point_entry:=public.mobile_fan_economy_post(owner,second_creator,'fan_point',-100,'exchange','e9500000-0000-4000-8000-000000000020',policy_b);
 ticket:=public.post_fan_ticket_entry(owner,second_creator,'credit',1,'fan_point_exchange','e9500000-0000-4000-8000-000000000020','e9500000-0000-4000-8000-000000000020',(select policy_version from public.reward_policy_activation where singleton),null,null);
 result:=jsonb_build_object('requestKey','e9500000-0000-4000-8000-000000000020','celebrityId',second_creator,'target','free_draw','units',1,'pointsSpent',100,'pointLedgerId',point_entry,'creditLedgerId',(ticket->>'entryId')::uuid,'policyVersion','cross-wallet-exchange-v1','createdAt',at_time,'replayed',false);
 insert into public.mobile_fan_economy_requests values(owner,'e9500000-0000-4000-8000-000000000020','exchange','{"celebritySlug":"cross-wallet-second","target":"free_draw","policyVersion":"cross-wallet-exchange-v1","units":1}',result,at_time);
 insert into public.group_wallet_cross_fixture values('legacy_exchange',result);
 perform public.cancel_owned_mobile_fan_economy_request(owner,'e9500000-0000-4000-8000-000000000021','exchange','{"celebritySlug":"cross-wallet-second","target":"free_draw","policyVersion":"cross-wallet-exchange-v1","units":1}');
 insert into public.mobile_vote_product_policies(store,product_id,version,vote_quantity,currency,effective_at)values('apple','cross-wallet-votes','cross-product-v1',9,'KRW',at_time)returning id into product;
 insert into public.mobile_vote_purchase_intents(id,app_user_id,celebrity_id,request_key,product_policy_id,vote_policy_id,store,product_id,vote_quantity,currency,policy_version)values(intent,owner,creator,extensions.gen_random_uuid(),product,policy_a,'apple','cross-wallet-votes',9,'KRW','cross-product-v1'),(pending,owner,creator,extensions.gen_random_uuid(),product,policy_a,'apple','cross-wallet-votes',9,'KRW','cross-product-v1');
 insert into public.mobile_vote_transactions(id,store,environment,external_transaction_id,intent_id,product_id,amount_krw,state,pending_reason,verification_fingerprint)values(tx,'apple','sandbox','cross-granted',intent,'cross-wallet-votes',900,'granted',null,'cross-fixture'),(extensions.gen_random_uuid(),'apple','sandbox','cross-pending',pending,'cross-wallet-votes',900,'pending','verification_pending','cross-fixture');
 insert into public.mobile_vote_purchase_lots(transaction_id,app_user_id,celebrity_id,quantity,spent,reversed,refund_review)values(tx,owner,creator,9,2,1,true);
 insert into public.group_wallet_cross_fixture values('paid_snapshot',jsonb_build_object('intents',(select jsonb_agg(to_jsonb(i)order by id)from public.mobile_vote_purchase_intents i where app_user_id=owner),'transactions',(select jsonb_agg(to_jsonb(t)order by t.id)from public.mobile_vote_transactions t join public.mobile_vote_purchase_intents i on i.id=t.intent_id where i.app_user_id=owner),'lots',(select jsonb_agg(to_jsonb(l)order by transaction_id)from public.mobile_vote_purchase_lots l where app_user_id=owner)));
 update public.group_wallet_release set enabled=true,write_fenced=false,legacy_writers_verified=true,migration_evidence_sha256=repeat('d',64),rewards_start_on=(clock_timestamp()at time zone'Asia/Seoul')::date;
 prior:=public.exchange_owned_mobile_fan_economy(owner,'e9500000-0000-4000-8000-000000000020','cross-wallet-second','free_draw','cross-wallet-exchange-v1',1);
 if prior is distinct from result||'{"replayed":true}'::jsonb or public.group_wallet_balance(owner,'fan_point')<>200 or public.group_wallet_balance(owner,'ticket')<>1 then raise exception 'Legacy lost-response replay changed original economics';end if;
 if public.read_owned_mobile_fan_economy_request(owner,'e9500000-0000-4000-8000-000000000021','exchange')->>'status'<>'cancelled'or public.read_owned_group_wallet_request(owner,'e9500000-0000-4000-8000-000000000020')->>'status'<>'legacy'then raise exception 'Legacy cancellation/receipt context lost';end if;
 result:=public.group_capsule_dispatch('create',actor,null,jsonb_build_object('requestKey',extensions.gen_random_uuid(),'name','Cross-feature fixture','blankWeight',0,'prizes',jsonb_build_array(jsonb_build_object('name','Fixture prize','weight',1000000,'stock',40))),allowlist);capsule:=(result->>'id')::uuid;
 perform public.group_capsule_dispatch('activate',actor,capsule,'{}',allowlist);
 insert into public.group_pages(id,kind,name)values(page,'hobby','Cross wallet fixture');insert into public.group_memberships(page_id,app_user_id,role)values(page,actor,'owner'),(page,owner,'member');
 insert into public.group_wallet_cross_fixture values('context',jsonb_build_object('owner',owner,'actor',actor,'allowlist',allowlist,'creator',creator,'creatorSlug',slug,'secondCreator',second_creator,'benefit',benefit,'legacyCampaign',campaign,'capsule',capsule,'page',page));
 raise notice 'PASS pre-cutover legacy exchange/receipt, cancellation tombstone and pending/held paid rights preserved into common wallet';
end $$;
commit;
